134		rootCmd.PersistentFlags().String("log-level", "info", "log verbosity level (debug, info, warn, error)")
135	
136		if err := viper.BindPFlag("demo", rootCmd.PersistentFlags().Lookup("demo")); err != nil {
137			panic(err)
138		}
139		if err := viper.BindPFlag("addr", rootCmd.PersistentFlags().Lookup("addr")); err != nil {
140			panic(err)
141		}
142		if err := viper.BindPFlag("port", rootCmd.PersistentFlags().Lookup("port")); err != nil {
143			panic(err)
144		}
145		if err := viper.BindPFlag("unix-sock", rootCmd.PersistentFlags().Lookup("unix-sock")); err != nil {
146			panic(err)
147		}
148		if err := viper.BindPFlag("data", rootCmd.PersistentFlags().Lookup("data")); err != nil {
149			panic(err)
150		}
151		if err := viper.BindPFlag("driver", rootCmd.PersistentFlags().Lookup("driver")); err != nil {
152			panic(err)
153		}
154		if err := viper.BindPFlag("dsn", rootCmd.PersistentFlags().Lookup("dsn")); err != nil {
155			panic(err)
156		}
157		if err := viper.BindPFlag("instance-url", rootCmd.PersistentFlags().Lookup("instance-url")); err != nil {
158			panic(err)
159		}
160		if err := viper.BindPFlag("allow-private-webhooks", rootCmd.PersistentFlags().Lookup("allow-private-webhooks")); err != nil {
161			panic(err)
162		}
163		if err := viper.BindPFlag("log-level", rootCmd.PersistentFlags().Lookup("log-level")); err != nil {
164			panic(err)
165		}
166	
167		viper.SetEnvPrefix("memos")
168		viper.SetEnvKeyReplacer(strings.NewReplacer("-", "_"))
169		viper.AutomaticEnv()
170	
171		rootCmd.AddCommand(versionCmd)
172	}
